def rate_cluster(folder,primary=True):
 rows=readlines(ROOT/folder/'results.jsonl');rows=[r for r in rows if (r['opponent']!='official-mage')==primary];seeds=sorted({r['seed'] for r in rows});means={s:sum(r['score'] for r in rows if r['seed']==s)/sum(r['seed']==s for r in rows) for s in seeds};rng=random.Random(438)
 boot=sorted(sum(means[rng.choice(seeds)] for _ in seeds)/len(seeds) for _ in range(5000));return [boot[125],boot[4874]]
def expected_greedy(p):
 return sum(math.comb(6,k)*p**k*(1-p)**(6-k)*(3 if k>=5 else 2 if k>=3 else 1 if k>=1 else 0) for k in range(7))

