 passed=(paired['primary']['gain_seed_cluster_95'][0]>0 and paired['primary']['gain']>=.02 and not over and not errors and not b['all']['forfeits'] and not b['all']['illegal'] and not b['all']['timeouts'] and not runtime['over_2s'] and not client['relay_deviations'] and not relay['relay_deviations'] and equiv['identical_actions']==equiv['cases'] and repro['same_outcomes']==56)
