 for name in ['p0','p1','p2','p3','t1','t2','t3','t4','t5','t6']:
  r=runs['experiments/program-'+name+'-development']['summary'];decision={'p0':'baseline','p1':'no gain','p2':'retain search direction','p3':'no total-win gain','t1':'retained parent'}.get(name,'not retained')
