 for label,q in [('F2 cold supervised CLI',runtime['cold_latency_s']),('F2 CLI including injected faults',runtime['all_latency_s'])]:lines.append(f"| {label} | {q['0.5']*1000:.3f} | {q['0.95']*1000:.3f} | {q['0.99']*1000:.3f} | {q['1']*1000:.3f} |")
